/* ============================================================================
   THE EMPTY CELLS — the 2026 audit's §4.2 / §4.3 content pass
   ----------------------------------------------------------------------------
   The bank is a diagonal stripe, not a grid: 92% of distinctive traits sit at
   intensity 3, 88% of signature at 4–5, 91% of common at 1–2. Within one
   category you could not ask for "a quiet, defining Loyalty-Bound trait",
   because that cell was empty even though both the rarity and the intensity
   existed elsewhere. Seven categories filled only 8 of their 20 cells; the
   thirteen Situational pools and every Appearance category filled 9–11.

   This file fills cells, by name, with the semantic justification the audit
   asks for rather than relabelling to move a statistic:

     quiet signature (i1–i2)  a rare, defining thing that is SMALL — a private
                              rule, a tell only intimates know, a thing done once
                              a year. Defining is not the same as loud.
     quiet distinctive (i1–i2) a recognisable, uncommon habit at low volume.
     loud common (i4–i5)      an ordinary behaviour done at full strength — most
                              people have a version of it; this person's is loud.
     uncommon i5              extreme but not rare: the kind of maximal behaviour
                              a whole profession or family produces.

   Appearance gets the deepest fill because it is the fixed-slot section drawing
   from the smallest local pools (34–44 entries; effective diversity ~25 at
   defaults). Situational personality pools were the most-drawn-from pools in the
   bank and had nothing above intensity 3 until the tails pass; this adds the
   quiet-rare and loud-ordinary ends.

   Every entry is reviewStatus:"reviewed" and names its conceptFamily so the
   near-duplicate review in the content studio can group it. Ids 160001+.
   ========================================================================== */
const TRAITS_CELLS = [
// ---------------------------------------------------------------- Attachment: Disorganized
{id:160001,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Keeps one drawer for the people who left",desc:"A quiet, exact archive of everyone who ever mattered, kept without bitterness and never mentioned.",example:"(a drawer of letters, tickets, one glove — labelled, dated, closed again)",intensity:1,rarity:"signature",pol:{mood:-1,disc:-1},conceptFamily:"attachment-archive",reviewStatus:"reviewed"},
{id:160002,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Says goodbye as if it might be the last one",desc:"Every parting carries a small extra weight — a held look, a second wave — that nobody else registers.",example:"(turns at the corner for one more look; has done since childhood)",intensity:2,rarity:"signature",pol:{mood:-1,disc:-1},conceptFamily:"attachment-parting",reviewStatus:"reviewed"},
{id:160003,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Tests the door before trusting the room",desc:"Small, repeated checks that someone is still there before letting themselves settle.",example:"You're still here? — Yes. — Good. Right. Good.",intensity:2,rarity:"distinctive",pol:{mood:-1,disc:-1},conceptFamily:"attachment-checking",reviewStatus:"reviewed"},
{id:160004,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Warm by text, wary in person",desc:"Affection flows freely at a distance and jams the moment they are in the same room.",example:"(three heart emojis; then, face to face, a handshake)",intensity:1,rarity:"distinctive",pol:{mood:-1,disc:-1},conceptFamily:"attachment-distance",reviewStatus:"reviewed"},
{id:160005,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Loves loudly, leaves loudly",desc:"Both the affection and the departures are theatrical — doors, declarations, returns.",example:"I'm DONE. — (back within the hour, with pastries)",intensity:4,rarity:"common",pol:{mood:-1,disc:-1},conceptFamily:"attachment-volatility",reviewStatus:"reviewed"},
{id:160006,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Needs you close and needs the window open",desc:"Wants proximity and an exit at the same time, and arranges every room for both.",example:"(sits nearest the person and nearest the door, always)",intensity:3,rarity:"common",pol:{mood:-1,disc:-1},conceptFamily:"attachment-exit",reviewStatus:"reviewed"},
{id:160007,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Apologises for being loved",desc:"Treats receiving care as a debt incurred and says sorry for it, reflexively.",example:"You didn't have to — sorry — thank you — sorry.",intensity:4,rarity:"uncommon",pol:{mood:-1,disc:-1},conceptFamily:"attachment-apology",reviewStatus:"reviewed"},
{id:160008,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Rewrites the relationship weekly",desc:"The story of what the two of them are changes with the week — ally, stranger, family, mistake.",example:"Last week we were basically siblings. This week I don't know what we are.",intensity:5,rarity:"uncommon",pol:{mood:-1,disc:-1},conceptFamily:"attachment-narrative",reviewStatus:"reviewed"},
{id:160009,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Panics at kindness, recovers at distance",desc:"Unexpected tenderness triggers a flinch; equilibrium returns only once they are alone.",example:"(the hug lands; they leave the party ten minutes later, fine by morning)",intensity:5,rarity:"distinctive",pol:{mood:-1,disc:-1},conceptFamily:"attachment-flinch",reviewStatus:"reviewed"},
{id:160010,section:"Attachment & Intimacy Style",category:"Disorganized",trait:"Loyal to the memory, not the person",desc:"Stays devoted to who someone was at their best, and treats the present version as an impostor.",example:"That's not him. The real him would never — that's not him.",intensity:3,rarity:"signature",pol:{mood:-1,disc:-1},conceptFamily:"attachment-memory",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Humor: Dry & Deadpan
{id:160011,section:"Humor Style",category:"Dry & Deadpan",trait:"One joke a year, remembered for decades",desc:"Almost never jokes; when they do, it is exact, and people quote it for years.",example:"(said one thing at the wedding in 2009; the family still uses it)",intensity:1,rarity:"signature",pol:{intel:1,emo:-1},conceptFamily:"deadpan-rarity",reviewStatus:"reviewed"},
{id:160012,section:"Humor Style",category:"Dry & Deadpan",trait:"Deadpan only for one person",desc:"Perfectly straight with everyone; a single confidant gets the bone-dry commentary.",example:"(to the room: nothing. To one person, sotto voce: 'He's doing the voice again.')",intensity:2,rarity:"signature",pol:{intel:1,emo:-1},conceptFamily:"deadpan-audience",reviewStatus:"reviewed"},
{id:160013,section:"Humor Style",category:"Dry & Deadpan",trait:"Fixes the punchline's syntax",desc:"Responds to a punchline by quietly fixing its syntax, which is the actual joke.",example:"'Fewer.' — What? — 'Fewer bodies.' Go on.",intensity:2,rarity:"distinctive",pol:{intel:1,emo:-1},conceptFamily:"deadpan-pedantry",reviewStatus:"reviewed"},
{id:160014,section:"Humor Style",category:"Dry & Deadpan",trait:"Flat 'no' as a complete comic form",desc:"A single toneless refusal, precisely placed, does the work of a routine.",example:"Want to hear my idea? — No.",intensity:1,rarity:"distinctive",pol:{intel:1,emo:-1},conceptFamily:"deadpan-refusal",reviewStatus:"reviewed"},
{id:160015,section:"Humor Style",category:"Dry & Deadpan",trait:"Narrates the disaster like a weather report",desc:"Ordinary dry commentary, delivered at full length and volume while everything falls apart.",example:"And now the ceiling. Right on schedule. Lovely. There goes the lamp.",intensity:4,rarity:"common",pol:{intel:1,emo:-1},conceptFamily:"deadpan-narration",reviewStatus:"reviewed"},
{id:160016,section:"Humor Style",category:"Dry & Deadpan",trait:"Sarcasm as the house language",desc:"The family or crew register is entirely dry; earnest statements have to be flagged.",example:"Genuinely, though. — Genuinely genuinely? — Genuinely genuinely.",intensity:3,rarity:"common",pol:{intel:1,emo:-1},conceptFamily:"deadpan-register",reviewStatus:"reviewed"},
{id:160017,section:"Humor Style",category:"Dry & Deadpan",trait:"Weaponised understatement at volume",desc:"The understatement is enormous and delivered to the whole room, which is the point.",example:"(to fifty people) Slight hiccup. The bridge is gone.",intensity:5,rarity:"common",pol:{intel:1,emo:-1},conceptFamily:"deadpan-understatement",reviewStatus:"reviewed"},
{id:160018,section:"Humor Style",category:"Dry & Deadpan",trait:"Has never once broken",desc:"Decades of delivery and not a single crack — the face is a professional instrument.",example:"(the whole table is crying with laughter; they are checking their watch)",intensity:5,rarity:"uncommon",pol:{intel:1,emo:-1},conceptFamily:"deadpan-composure",reviewStatus:"reviewed"},
{id:160019,section:"Humor Style",category:"Dry & Deadpan",trait:"Answers the literal question, on purpose",desc:"Takes every rhetorical question at face value and answers it flatly, for effect.",example:"Can you believe this? — Yes. I was there.",intensity:4,rarity:"uncommon",pol:{intel:1,emo:-1},conceptFamily:"deadpan-literal",reviewStatus:"reviewed"},
{id:160020,section:"Humor Style",category:"Dry & Deadpan",trait:"Funniest in writing, blank in the room",desc:"On the page every line lands; in person the same lines arrive without inflection and mostly miss.",example:"(the email is hilarious. The meeting is not.)",intensity:4,rarity:"distinctive",pol:{intel:1,emo:-1},conceptFamily:"deadpan-medium",reviewStatus:"reviewed"},
{id:160021,section:"Humor Style",category:"Dry & Deadpan",trait:"The pause is the punchline",desc:"Rarely says anything funny; the silence after someone else's line is where the comedy is.",example:"(a four-second look, then: 'Right.')",intensity:3,rarity:"signature",pol:{intel:1,emo:-1},conceptFamily:"deadpan-timing",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Humor: Cruel & Barbed
{id:160022,section:"Humor Style",category:"Cruel & Barbed",trait:"One nickname that never healed",desc:"Cruelty in a single, permanent name for someone — used rarely, and it still lands every time.",example:"(has called the brother 'the spare' for thirty years; says it once a Christmas)",intensity:1,rarity:"signature",pol:{warm:-1,agr:-1},conceptFamily:"barbed-nickname",reviewStatus:"reviewed"},
{id:160023,section:"Humor Style",category:"Cruel & Barbed",trait:"Saves the knife for the people they love",desc:"Kind to strangers; the barbs are reserved, quietly, for intimates who cannot leave.",example:"(charming to the waiter. Then, to the spouse, very softly, the thing about the weight.)",intensity:2,rarity:"signature",pol:{warm:-1,agr:-1},conceptFamily:"barbed-intimate",reviewStatus:"reviewed"},
{id:160024,section:"Humor Style",category:"Cruel & Barbed",trait:"Compliments with a delayed sting",desc:"Praise that turns over in the mind a minute later and reveals its edge.",example:"You're so brave to wear that. — (pause) — Wait.",intensity:2,rarity:"distinctive",pol:{warm:-1,agr:-1},conceptFamily:"barbed-compliment",reviewStatus:"reviewed"},
{id:160025,section:"Humor Style",category:"Cruel & Barbed",trait:"Barbs only in the retelling",desc:"Pleasant in the moment; the cruelty arrives later, in how they describe you to others.",example:"(lovely to your face. The version at dinner has you as a punchline.)",intensity:1,rarity:"distinctive",pol:{warm:-1,agr:-1},conceptFamily:"barbed-retelling",reviewStatus:"reviewed"},
{id:160026,section:"Humor Style",category:"Cruel & Barbed",trait:"Roasts the room and calls it love",desc:"Loud, general, indiscriminate mockery presented as affection — and mostly received as it.",example:"Look at this lot. Absolute state of you. Come here.",intensity:4,rarity:"common",pol:{warm:-1,agr:-1},conceptFamily:"barbed-roast",reviewStatus:"reviewed"},
{id:160027,section:"Humor Style",category:"Cruel & Barbed",trait:"Every joke needs a target",desc:"Cannot be funny without someone in the room paying for it.",example:"(scans the table for who's weakest today; begins)",intensity:3,rarity:"common",pol:{warm:-1,agr:-1},conceptFamily:"barbed-target",reviewStatus:"reviewed"},
{id:160028,section:"Humor Style",category:"Cruel & Barbed",trait:"Draws blood, then buys the round",desc:"Loud cruelty followed by loud generosity, in a cycle everyone around them has learned to ride.",example:"— and that's why nobody's married you. Drinks! Drinks on me!",intensity:5,rarity:"common",pol:{warm:-1,agr:-1},conceptFamily:"barbed-cycle",reviewStatus:"reviewed"},
{id:160029,section:"Humor Style",category:"Cruel & Barbed",trait:"Professionally cruel",desc:"The barbs are a job — critic, drill sergeant, comic — and off duty it runs on anyway.",example:"That's not a performance, it's a cry for help. — We're at your niece's recital.",intensity:5,rarity:"uncommon",pol:{warm:-1,agr:-1},conceptFamily:"barbed-professional",reviewStatus:"reviewed"},
{id:160030,section:"Humor Style",category:"Cruel & Barbed",trait:"Mocks the thing you told them in confidence",desc:"Takes a private disclosure and, later, makes it the joke — reliably enough that people stop confiding.",example:"(you mentioned the fear of dogs once. It's been a bit for a year.)",intensity:4,rarity:"uncommon",pol:{warm:-1,agr:-1},conceptFamily:"barbed-confidence",reviewStatus:"reviewed"},
{id:160031,section:"Humor Style",category:"Cruel & Barbed",trait:"Cruel to themselves first, then to you",desc:"Opens with brutal self-mockery as licence, then turns the same blade outward.",example:"I'm a disaster, obviously. But you — you're a disaster with a mortgage.",intensity:4,rarity:"distinctive",pol:{warm:-1,agr:-1},conceptFamily:"barbed-licence",reviewStatus:"reviewed"},
{id:160032,section:"Humor Style",category:"Cruel & Barbed",trait:"The quiet line that ends the evening",desc:"Speaks rarely; one soft, precise cruelty that empties the room is the whole repertoire.",example:"(barely audible) At least your father didn't have to see it.",intensity:3,rarity:"signature",pol:{warm:-1,agr:-1},conceptFamily:"barbed-quiet",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Humor: Absurd & Chaotic
{id:160033,section:"Humor Style",category:"Absurd & Chaotic",trait:"One recurring imaginary colleague",desc:"A single, decades-old invented character who is occasionally blamed, quoted, or asked after.",example:"Gerald's not coming. Gerald's never coming. (Gerald has never existed.)",intensity:1,rarity:"signature",pol:{disc:-1,rebel:1},conceptFamily:"absurd-recurring",reviewStatus:"reviewed"},
{id:160034,section:"Humor Style",category:"Absurd & Chaotic",trait:"Serious face, one absurd object",desc:"Entirely grown-up in manner; carries or keeps a single ridiculous thing and never explains it.",example:"(the briefcase contains, among the contracts, a rubber duck in a tiny hat)",intensity:2,rarity:"signature",pol:{disc:-1,rebel:1},conceptFamily:"absurd-object",reviewStatus:"reviewed"},
{id:160035,section:"Humor Style",category:"Absurd & Chaotic",trait:"Mislabels things on purpose, quietly",desc:"Low-key relabelling of the world — the cat is 'the accountant', the car is 'the cathedral'.",example:"Put it in the cathedral. — The car? — The cathedral.",intensity:2,rarity:"distinctive",pol:{disc:-1,rebel:1},conceptFamily:"absurd-relabel",reviewStatus:"reviewed"},
{id:160036,section:"Humor Style",category:"Absurd & Chaotic",trait:"Small surreal footnotes",desc:"Appends a tiny impossible detail to ordinary statements, without emphasis.",example:"Back at six. Unless the moon's early again.",intensity:1,rarity:"distinctive",pol:{disc:-1,rebel:1},conceptFamily:"absurd-footnote",reviewStatus:"reviewed"},
{id:160037,section:"Humor Style",category:"Absurd & Chaotic",trait:"Loud bit, no off switch",desc:"Ordinary silliness at full volume, kept going long after the room has moved on.",example:"(still doing the walrus voice; the meeting started twelve minutes ago)",intensity:4,rarity:"common",pol:{disc:-1,rebel:1},conceptFamily:"absurd-volume",reviewStatus:"reviewed"},
{id:160038,section:"Humor Style",category:"Absurd & Chaotic",trait:"Invents a game for any wait",desc:"Any queue, delay or lull becomes a nonsense competition with rules made up on the spot.",example:"First to spot a hat wins. Hats are worth three. Berets are void.",intensity:3,rarity:"common",pol:{disc:-1,rebel:1},conceptFamily:"absurd-game",reviewStatus:"reviewed"},
{id:160039,section:"Humor Style",category:"Absurd & Chaotic",trait:"Answers the phone in character",desc:"Every call, every time, a different voice and name before their own — loudly, to anyone.",example:"Harbourmaster's office. — Mum, it's me. — Harbourmaster's office, Mum.",intensity:5,rarity:"common",pol:{disc:-1,rebel:1},conceptFamily:"absurd-phone",reviewStatus:"reviewed"},
{id:160040,section:"Humor Style",category:"Absurd & Chaotic",trait:"Full costume for a minor point",desc:"Will go to extraordinary, physical lengths to land a joke nobody asked for.",example:"(arrives at the budget meeting dressed as the budget)",intensity:5,rarity:"uncommon",pol:{disc:-1,rebel:1},conceptFamily:"absurd-effort",reviewStatus:"reviewed"},
{id:160041,section:"Humor Style",category:"Absurd & Chaotic",trait:"Argues the absurd position to the end",desc:"Takes a ridiculous stance and defends it at full seriousness until everyone gives up.",example:"The moon is a door. Show me where I'm wrong. Show me.",intensity:4,rarity:"uncommon",pol:{disc:-1,rebel:1},conceptFamily:"absurd-defence",reviewStatus:"reviewed"},
{id:160042,section:"Humor Style",category:"Absurd & Chaotic",trait:"Nonsense to defuse, every single time",desc:"Any tension in the room triggers an immediate surreal detour, loud and unmissable.",example:"(the argument peaks) RIGHT. Who here has eaten a swan. Hands up.",intensity:4,rarity:"distinctive",pol:{disc:-1,rebel:1},conceptFamily:"absurd-defuse",reviewStatus:"reviewed"},
{id:160043,section:"Humor Style",category:"Absurd & Chaotic",trait:"Builds a private mythology, slowly",desc:"Over years, a quiet invented cosmology of household gods, feuds and holidays that only insiders know.",example:"It's the Feast of the Lost Sock. We don't do laundry. It's law.",intensity:3,rarity:"signature",pol:{disc:-1,rebel:1},conceptFamily:"absurd-mythology",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Values: Idealistic & Visionary
{id:160044,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Keeps a private list of what should exist",desc:"A quiet, years-old notebook of things the world is missing — never shown, occasionally acted on.",example:"(page forty: 'a library that lends tools.' Page forty-one: it opened.)",intensity:1,rarity:"signature",pol:{hon:1,pos:1},conceptFamily:"idealist-list",reviewStatus:"reviewed"},
{id:160045,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"One vow, kept without mention",desc:"Made a single private promise about how they would live, decades ago, and has never broken or discussed it.",example:"(has never, once, taken the bigger slice. Nobody knows it's a rule.)",intensity:2,rarity:"signature",pol:{hon:1,pos:1},conceptFamily:"idealist-vow",reviewStatus:"reviewed"},
{id:160046,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Small fixes toward the big picture",desc:"Idealism expressed only as tiny, local, repeated improvements — never speeches.",example:"(fixes the same bench every spring; has opinions about benches, and cities)",intensity:2,rarity:"distinctive",pol:{hon:1,pos:1},conceptFamily:"idealist-local",reviewStatus:"reviewed"},
{id:160047,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Believes better is possible, says so once",desc:"Quietly optimistic about what could be, and states it exactly one time per argument, then lets it sit.",example:"It doesn't have to be like this. (and then nothing more; it lands anyway)",intensity:1,rarity:"distinctive",pol:{hon:1,pos:1},conceptFamily:"idealist-once",reviewStatus:"reviewed"},
{id:160048,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Loud about the future at every dinner",desc:"Ordinary, sincere, frequent talk of how things ought to be, at a volume that reorganises the table.",example:"No, listen, in ten years — no, LISTEN — in ten years none of this—",intensity:4,rarity:"common",pol:{hon:1,pos:1},conceptFamily:"idealist-dinner",reviewStatus:"reviewed"},
{id:160049,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Signs every petition, means every one",desc:"A common, earnest, unfiltered idealism that says yes to every cause put in front of it.",example:"(has signed four things today and will read about them on the bus)",intensity:3,rarity:"common",pol:{hon:1,pos:1},conceptFamily:"idealist-yes",reviewStatus:"reviewed"},
{id:160050,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Quits on principle, publicly, again",desc:"Has walked out of more than one job, group or family dinner over what should be true, loudly each time.",example:"Then I can't be part of this. (coat. door. the third time this year.)",intensity:5,rarity:"common",pol:{hon:1,pos:1},conceptFamily:"idealist-walkout",reviewStatus:"reviewed"},
{id:160051,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Gave the house away for the cause",desc:"Has made a real, irreversible material sacrifice for a vision, and would again.",example:"It was just a house. It's a school now. That's a better use of walls.",intensity:5,rarity:"uncommon",pol:{hon:1,pos:1},conceptFamily:"idealist-sacrifice",reviewStatus:"reviewed"},
{id:160052,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Sees the finished thing already",desc:"Talks about what does not yet exist in the present tense, with detail, and recruits by it.",example:"So you come in here — through the atrium, obviously — and the first thing you see—",intensity:4,rarity:"uncommon",pol:{hon:1,pos:1},conceptFamily:"idealist-vision",reviewStatus:"reviewed"},
{id:160053,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Refuses the compromise everyone else took",desc:"Alone in the room in declining the workable deal, on the grounds that it is not right yet.",example:"Everyone else signed. — Everyone else is wrong. Politely. But wrong.",intensity:4,rarity:"distinctive",pol:{hon:1,pos:1},conceptFamily:"idealist-holdout",reviewStatus:"reviewed"},
{id:160054,section:"Values & Moral Line",category:"Idealistic & Visionary",trait:"Plants the shade they'll never use",desc:"A steady, unshowy commitment to long work whose payoff is for others, explained only if asked.",example:"Forty years to shade. I'll be gone. That's rather the point.",intensity:3,rarity:"signature",pol:{hon:1,pos:1},conceptFamily:"idealist-long",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Values: Loyalty-Bound
{id:160055,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Still sends the birthday card",desc:"Decades after the falling-out, the card arrives every year, unsigned by anything but habit and loyalty.",example:"(no note. Same card as always. Thirty-one years running.)",intensity:1,rarity:"signature",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-card",reviewStatus:"reviewed"},
{id:160056,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Keeps the old team's secrets at the new job",desc:"Quietly carries confidences from people they no longer work with, and would sooner leave than use them.",example:"I know how they did it. — And? — And I worked there.",intensity:2,rarity:"signature",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-secrets",reviewStatus:"reviewed"},
{id:160057,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Defends them in their absence, mildly",desc:"A small, reliable correction whenever an absent friend is criticised — never a fight, never skipped.",example:"He's not lazy. He's tired. There's a difference. Anyway.",intensity:2,rarity:"distinctive",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-absent",reviewStatus:"reviewed"},
{id:160058,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Remembers who was there",desc:"Keeps a quiet, accurate account of who showed up when it mattered, and lets it steer small favours for years.",example:"(the one who came to the hospital gets the good seat, every time, without comment)",intensity:1,rarity:"distinctive",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-ledger",reviewStatus:"reviewed"},
{id:160059,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Fights anyone who slights the family",desc:"Ordinary, immediate, loud tribal defence — the moment a relative is mocked, they are in it.",example:"Say that about my sister again. Go on. Say it.",intensity:4,rarity:"common",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-fight",reviewStatus:"reviewed"},
{id:160060,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Wears the colours everywhere",desc:"Loyalty as visible allegiance — the club, the town, the unit — displayed constantly and unironically.",example:"(the scarf, the mug, the tattoo, the ringtone)",intensity:3,rarity:"common",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-colours",reviewStatus:"reviewed"},
{id:160061,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Drops everything, every time, for the call",desc:"Any summons from their people is answered at once, at full volume, whatever it costs.",example:"(leaves the wedding. It was the wrong wedding to leave. Would do it again.)",intensity:5,rarity:"common",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-summons",reviewStatus:"reviewed"},
{id:160062,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Took the sentence for someone else",desc:"Has paid a real, public price — a job, a record, a reputation — to shield one of their own.",example:"I said it was me. — It wasn't you. — I said it was.",intensity:5,rarity:"uncommon",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-sentence",reviewStatus:"reviewed"},
{id:160063,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Follows the leader off the cliff",desc:"Will back the person they've chosen through obvious error, out loud, without hedging.",example:"If she says it's north, it's north. — It's south. — Then it's south and I'm with her.",intensity:4,rarity:"uncommon",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-cliff",reviewStatus:"reviewed"},
{id:160064,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Cuts off the friend who crossed the family",desc:"A visible, decisive severing of a real friendship the moment it conflicted with kin.",example:"Twenty years. And he said that about Dad. So: nineteen years, then.",intensity:4,rarity:"distinctive",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-severing",reviewStatus:"reviewed"},
{id:160065,section:"Values & Moral Line",category:"Loyalty-Bound",trait:"Loyal to the dead more than the living",desc:"Decisions are still quietly referred to someone gone — what they would have wanted outranks the room.",example:"He'd have hated it. So no. (he has been dead eleven years)",intensity:3,rarity:"signature",pol:{warm:1,agr:1,rebel:-1},conceptFamily:"loyal-dead",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Values: Self-Interested
{id:160066,section:"Values & Moral Line",category:"Self-Interested",trait:"Keeps one escape fund nobody knows about",desc:"A quiet, exact reserve — money, a key, a contact — held against the day everyone else becomes a cost.",example:"(the second account. The spouse doesn't know. It's been there since before the spouse.)",intensity:1,rarity:"signature",pol:{warm:-1,hon:-1},conceptFamily:"selfish-reserve",reviewStatus:"reviewed"},
{id:160067,section:"Values & Moral Line",category:"Self-Interested",trait:"Always takes the seat facing the exit",desc:"Small, invariable self-positioning — best view, quickest way out — done so smoothly nobody objects.",example:"(somehow, again, the chair with its back to the wall)",intensity:2,rarity:"signature",pol:{warm:-1,hon:-1},conceptFamily:"selfish-seat",reviewStatus:"reviewed"},
{id:160068,section:"Values & Moral Line",category:"Self-Interested",trait:"Rounds every split in their favour",desc:"Never openly unfair; the bill, the credit and the chores just consistently come out a little their way.",example:"Call it forty each. — It's forty-two. — Call it forty.",intensity:2,rarity:"distinctive",pol:{warm:-1,hon:-1},conceptFamily:"selfish-rounding",reviewStatus:"reviewed"},
{id:160069,section:"Values & Moral Line",category:"Self-Interested",trait:"Helps when it's on the way",desc:"Genuinely useful whenever helping costs nothing extra; quietly unavailable the moment it would.",example:"Happy to drop it off, I'm passing anyway. — And Tuesday? — Tuesday I'm not passing.",intensity:1,rarity:"distinctive",pol:{warm:-1,hon:-1},conceptFamily:"selfish-convenience",reviewStatus:"reviewed"},
{id:160070,section:"Values & Moral Line",category:"Self-Interested",trait:"Says 'what about me?' out loud",desc:"Ordinary self-concern, unfiltered and frequent — every plan is checked against their own comfort, audibly.",example:"Fine, but where do I sit? No, seriously, where do I sit?",intensity:4,rarity:"common",pol:{warm:-1,hon:-1},conceptFamily:"selfish-vocal",reviewStatus:"reviewed"},
{id:160071,section:"Values & Moral Line",category:"Self-Interested",trait:"First to the buffet, every time",desc:"Uncomplicated, visible appetite for the best of whatever is on offer, before anyone else has moved.",example:"(the good chair, the first plate, the window seat — claimed, cheerfully)",intensity:3,rarity:"common",pol:{warm:-1,hon:-1},conceptFamily:"selfish-buffet",reviewStatus:"reviewed"},
{id:160072,section:"Values & Moral Line",category:"Self-Interested",trait:"Bails loudly the moment it stops paying",desc:"Leaves any arrangement the instant it costs more than it returns, and announces the arithmetic.",example:"This isn't working for me any more. So. That's that.",intensity:5,rarity:"common",pol:{warm:-1,hon:-1},conceptFamily:"selfish-exit",reviewStatus:"reviewed"},
{id:160073,section:"Values & Moral Line",category:"Self-Interested",trait:"Sold the friend for the promotion",desc:"Has made one large, deliberate trade of a person for an advantage and does not pretend otherwise.",example:"Someone was going to get the job. I made sure it was me. That's all that happened.",intensity:5,rarity:"uncommon",pol:{warm:-1,hon:-1},conceptFamily:"selfish-trade",reviewStatus:"reviewed"},
{id:160074,section:"Values & Moral Line",category:"Self-Interested",trait:"Negotiates with family like strangers",desc:"Full, unembarrassed bargaining with kin — terms, leverage, walk-away points.",example:"I'll do Christmas if you do the airport. Both ways. In writing.",intensity:4,rarity:"uncommon",pol:{warm:-1,hon:-1},conceptFamily:"selfish-kin",reviewStatus:"reviewed"},
{id:160075,section:"Values & Moral Line",category:"Self-Interested",trait:"Charms for exactly as long as it's useful",desc:"Warmth switched on and off by return on investment, visibly enough that the pattern becomes known.",example:"(delightful until the introductions were made; hasn't looked back since)",intensity:4,rarity:"distinctive",pol:{warm:-1,hon:-1},conceptFamily:"selfish-charm",reviewStatus:"reviewed"},
{id:160076,section:"Values & Moral Line",category:"Self-Interested",trait:"Honest about the selfishness",desc:"Never pretends to a principle they don't hold — a quiet, consistent candour about looking after number one.",example:"I'm not going to help. I want to be clear that it's not because I can't.",intensity:3,rarity:"signature",pol:{warm:-1,hon:1},conceptFamily:"selfish-candour",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Situational personality pools (four per axis)
{id:160077,section:"Personality Traits",category:"Friendliness — Situational",trait:"Warm only in the kitchen",desc:"Guarded everywhere; put them at a stove with someone and they become the friendliest person alive.",example:"(monosyllabic in the sitting room. Sings while chopping. Feeds you three times.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-place",reviewStatus:"reviewed",conditions:["home"]},
{id:160078,section:"Personality Traits",category:"Friendliness — Situational",trait:"Effusive with the crowd, blank with the friend",desc:"Big, loud warmth for audiences; oddly flat once it's just the two of you.",example:"(hugged forty strangers at the launch. Nodded at you.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-audience",reviewStatus:"reviewed",conditions:["public"]},
{id:160079,section:"Personality Traits",category:"Friendliness — Situational",trait:"Friendly to whoever is losing",desc:"Warmth follows the underdog in any room and withdraws from whoever is winning.",example:"(cold to the boss all meeting; kind to the intern who fumbled the slides)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-underdog",reviewStatus:"reviewed"},
{id:160080,section:"Personality Traits",category:"Friendliness — Situational",trait:"Cold on Mondays, only Mondays",desc:"A fixed, faintly comic weekly cycle: unapproachable at the start of the week, ordinary by Tuesday.",example:"Don't. It's Monday. — It's Tuesday. — Oh. Hello then!",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-cycle",reviewStatus:"reviewed"},
{id:160081,section:"Personality Traits",category:"Honesty — Situational",trait:"Truthful under oath, only",desc:"Lies freely in daily life and becomes scrupulously exact the instant something is formal or sworn.",example:"(a fantasist at dinner; a model witness)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-formal",reviewStatus:"reviewed",conditions:["authority"]},
{id:160082,section:"Personality Traits",category:"Honesty — Situational",trait:"Blurts the truth when tired",desc:"Diplomatic all day; past a certain hour the filter fails loudly and completely.",example:"(11pm) I've never liked the curtains. Or Steve. — What? — What?",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-fatigue",reviewStatus:"reviewed",conditions:["fatigue"]},
{id:160083,section:"Personality Traits",category:"Honesty — Situational",trait:"Honest with children, evasive with adults",desc:"Straight answers for anyone under twelve; grown-ups get the managed version.",example:"Yes, Grandad's dying. — (to the adults) He's comfortable.",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-children",reviewStatus:"reviewed",conditions:["dependent"]},
{id:160084,section:"Personality Traits",category:"Honesty — Situational",trait:"Won't lie in writing",desc:"Verbal fibs come easily; anything on paper or screen is scrupulously true, so they avoid writing.",example:"Just call me. Don't email. I can't— just call.",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-medium",reviewStatus:"reviewed"},
{id:160085,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Takes the room only for other people",desc:"Never pushes for themselves; will flatten a committee on someone else's behalf.",example:"(silent about their own pay for years. Got the junior a raise in one meeting.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-proxy",reviewStatus:"reviewed"},
{id:160086,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Bossy in the car, meek on foot",desc:"Command instincts that switch on with a steering wheel and off the moment they get out.",example:"LEFT. LEFT. — (parks) — Um, do you think we should go in?",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-vehicle",reviewStatus:"reviewed"},
{id:160087,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Assertive with strangers, pushover at home",desc:"Fearsome to shopkeepers and officials; loses every argument with their own family, at full volume.",example:"(made the airline cry. Cannot get the teenager to bring a plate down.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-home",reviewStatus:"reviewed",conditions:["stranger","home"]},
{id:160088,section:"Personality Traits",category:"Assertiveness — Situational",trait:"Asserts by leaving the room",desc:"Never argues; quietly exits, and the exit does the work an argument would have.",example:"(stands, collects the cup, goes. The meeting reconsiders.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-exit",reviewStatus:"reviewed"},
{id:160089,section:"Personality Traits",category:"Confidence — Situational",trait:"Sure on the tools, lost in the office",desc:"Total assurance with the work itself; visibly adrift the moment it becomes meetings and forms.",example:"(fixed the turbine blind. Couldn't find the courage to ask where the toilet was.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-domain",reviewStatus:"reviewed",conditions:["work"]},
{id:160090,section:"Personality Traits",category:"Confidence — Situational",trait:"Confident until a specific person walks in",desc:"Ordinary self-assurance that collapses, audibly, in the presence of one particular figure.",example:"(fine. Fine. Fine. — Oh. Dad's here. — (voice goes))",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-person",reviewStatus:"reviewed"},
{id:160091,section:"Personality Traits",category:"Confidence — Situational",trait:"Fearless in a crisis, jelly afterwards",desc:"Absolute composure while it's happening; the shaking, doubt and apologies arrive once it's over.",example:"(ran into the building. Sat in the car for an hour after. Couldn't hold the keys.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-aftermath",reviewStatus:"reviewed",conditions:["threat"]},
{id:160092,section:"Personality Traits",category:"Confidence — Situational",trait:"Sure-footed in a second language",desc:"Hesitant and self-doubting in their mother tongue; oddly bold and direct in another.",example:"(in English, apologises constantly. In Portuguese, tells the mayor what's wrong with the bridge.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-language",reviewStatus:"reviewed"},
{id:160093,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Agrees to everything from the person they fear",desc:"Argumentative with everyone except one figure, to whom they say yes before the sentence ends.",example:"(fought the council for a year. Said 'of course' to her mother before hearing the question.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-fear",reviewStatus:"reviewed"},
{id:160094,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Loud yes-man in meetings, grumbler after",desc:"Enthusiastic agreement in the room; the objections come out afterwards, at length, to anyone.",example:"Great plan! Love it! — (corridor) — It'll never work. It'll never work.",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-corridor",reviewStatus:"reviewed",conditions:["public","private"]},
{id:160095,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Contrarian only when it's safe",desc:"Fierce disagreement with people who can't hurt them; instant compliance with anyone who can.",example:"(furious at the waiter. 'Absolutely, yes, sorry' to the landlord.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-safety",reviewStatus:"reviewed",conditions:["authority"]},
{id:160096,section:"Personality Traits",category:"Agreeableness — Situational",trait:"Concedes with a small delay",desc:"Always ends up agreeing; always takes a quiet moment first, so it reads as considered.",example:"...(three seconds)... Yes. All right. Yes.",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-delay",reviewStatus:"reviewed"},
{id:160097,section:"Personality Traits",category:"Manners — Situational",trait:"Impeccable to the help, rude to the host",desc:"Courtesy runs inverse to status: staff get warmth and thanks, hosts and bosses get the edge.",example:"(thanks the cloakroom attendant by name. Doesn't say hello to the minister.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-status",reviewStatus:"reviewed"},
{id:160098,section:"Personality Traits",category:"Manners — Situational",trait:"Formal at the table, feral on the sofa",desc:"Ordinary, loud domestic contrast — dinner manners immaculate; the rest of the evening is elbows.",example:"(napkin on lap, elbows off. Twenty minutes later, eating crisps out of the packet on the floor.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-table",reviewStatus:"reviewed",conditions:["home"]},
{id:160099,section:"Personality Traits",category:"Manners — Situational",trait:"Manners vanish behind a wheel",desc:"Gracious pedestrian, monstrous driver — the transformation is total and well known.",example:"(held the door for six people. Then, in the car: language.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-vehicle",reviewStatus:"reviewed"},
{id:160100,section:"Personality Traits",category:"Manners — Situational",trait:"Polite in the second person only",desc:"Courtesy to whoever they're addressing; the same people are described bluntly the moment they leave.",example:"Lovely to see you! — (door closes) — What a waste of a chair.",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-absent",reviewStatus:"reviewed"},
{id:160101,section:"Personality Traits",category:"Discipline — Situational",trait:"Ritual at dawn, chaos after",desc:"One immovable early routine — the run, the prayer, the page — and no structure of any kind afterward.",example:"(five a.m., every day, for twenty years. By nine: anything could happen.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-dawn",reviewStatus:"reviewed"},
{id:160102,section:"Personality Traits",category:"Discipline — Situational",trait:"Military about food, hopeless about money",desc:"Total control in one domain, visible disorder in another, both at full volume.",example:"(meal-prepped for the month. Overdrawn by the ninth.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-domain",reviewStatus:"reviewed"},
{id:160103,section:"Personality Traits",category:"Discipline — Situational",trait:"Disciplined only under a deadline",desc:"Nothing moves without a hard date; with one, they become a machine that alarms the people around them.",example:"(nine weeks of nothing. Then forty-eight hours in which the whole thing was built.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-deadline",reviewStatus:"reviewed",conditions:["work"]},
{id:160104,section:"Personality Traits",category:"Discipline — Situational",trait:"Tidy for guests, not for self",desc:"The house is immaculate when someone is coming and a quiet wreck when nobody is.",example:"(the doorbell is the only cleaning schedule)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-guests",reviewStatus:"reviewed",conditions:["home"]},
{id:160105,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Obeys the uniform, defies the person",desc:"Follows any rule that comes from an institution; bristles at the identical rule from an individual.",example:"The sign says no. — Fine. — I say no. — Why should you get to?",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-institution",reviewStatus:"reviewed",conditions:["authority"]},
{id:160106,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Rebel in the group chat, model citizen in person",desc:"Loud defiance online or among friends; complete compliance the moment an authority is actually present.",example:"(the messages are incendiary. The meeting is 'yes sir'.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-online",reviewStatus:"reviewed",worldTags:["online"],conditions:["public"]},
{id:160107,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Breaks every rule but their own",desc:"Contemptuous of imposed rules; ferociously, visibly strict about a personal code nobody else can see.",example:"(ignores the speed limit. Has never once been late to a promise.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-own-code",reviewStatus:"reviewed"},
{id:160108,section:"Personality Traits",category:"Rebelliousness — Situational",trait:"Complies, then does it their way anyway",desc:"Never argues with an instruction; quietly executes a different plan and reports success.",example:"Absolutely. — (does the opposite. It works. Nobody asks.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-quiet-defiance",reviewStatus:"reviewed"},
{id:160109,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Cries at films, dry at funerals",desc:"Feeling flows freely for fiction and jams for anything real — a private rule they can't explain.",example:"(wept at the cartoon. Gave the eulogy without a tremor.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-fiction",reviewStatus:"reviewed"},
{id:160110,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Big feelings, only in the car",desc:"Composed indoors; the drive home is where all of it comes out, loudly, with the radio up.",example:"(fine at the hospital. Screamed the whole ring road.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-vehicle",reviewStatus:"reviewed",conditions:["private"]},
{id:160111,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Feels it for animals, not people",desc:"Enormous, open tenderness for any creature; a strange, visible flatness about human suffering.",example:"(inconsolable about the fox. 'These things happen' about the cousin.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-animals",reviewStatus:"reviewed"},
{id:160112,section:"Personality Traits",category:"Emotional Capacity — Situational",trait:"Open for exactly one drink",desc:"A brief, reliable window of candour after the first glass, closed again by the second.",example:"(the truth arrives with the first pint and leaves with the second)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-drink",reviewStatus:"reviewed"},
{id:160113,section:"Personality Traits",category:"Intelligence — Situational",trait:"Brilliant on paper, mute in the room",desc:"Analysis that is exact and deep in writing and simply does not arrive when spoken to.",example:"(the memo solved it. In the meeting: 'Um. Yes. As the memo says.')",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-medium",reviewStatus:"reviewed"},
{id:160114,section:"Personality Traits",category:"Intelligence — Situational",trait:"Sharp about others, blind about self",desc:"Reads everyone else's situation instantly and loudly; cannot see the identical pattern in their own.",example:"He's obviously sabotaging himself. — And you? — What about me?",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-blindspot",reviewStatus:"reviewed"},
{id:160115,section:"Personality Traits",category:"Intelligence — Situational",trait:"Analytical only when angry",desc:"Vague and intuitive by default; fury makes them suddenly, frighteningly precise.",example:"(usually 'whatever'. Provoked: a numbered list of your errors, with dates.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-anger",reviewStatus:"reviewed"},
{id:160116,section:"Personality Traits",category:"Intelligence — Situational",trait:"Thinks clearly only while walking",desc:"Needs to be moving to reason at all; seated, the argument won't come.",example:"Hang on — let me walk. (three laps of the yard; then the answer)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-motion",reviewStatus:"reviewed"},
{id:160117,section:"Personality Traits",category:"Positivity — Situational",trait:"Optimist about strangers, pessimist about kin",desc:"Expects the best of anyone they've just met and the worst of everyone they're related to.",example:"He'll be fine, he's a good lad. — He's your son. — Oh, HIM. No.",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-kin",reviewStatus:"reviewed"},
{id:160118,section:"Personality Traits",category:"Positivity — Situational",trait:"Doom before breakfast, sunshine after",desc:"A loud, reliable daily arc from catastrophe to cheer, tied entirely to food and coffee.",example:"We're all going to lose everything. — (toast) — Actually it's a lovely day.",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-breakfast",reviewStatus:"reviewed"},
{id:160119,section:"Personality Traits",category:"Positivity — Situational",trait:"Hopeful only about other people's plans",desc:"Boundless faith in everyone else's ventures; certain, loud doom about their own.",example:"Yours will work, obviously. Mine? Mine's a joke. Yours, though — yours!",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-proxy",reviewStatus:"reviewed"},
{id:160120,section:"Personality Traits",category:"Positivity — Situational",trait:"Cheerful in weather, bleak indoors",desc:"Outlook that tracks the sky exactly — outside, all is possible; under a roof, nothing is.",example:"(a different person on the hill. Comes back in and sighs.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-weather",reviewStatus:"reviewed"},
{id:160121,section:"Personality Traits",category:"Activeness — Situational",trait:"Still for hours, then a sudden mile",desc:"Long, motionless stretches broken by abrupt bursts of physical activity nobody predicted.",example:"(four hours in the chair. Then, without warning, up the hill at a run.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-burst",reviewStatus:"reviewed"},
{id:160122,section:"Personality Traits",category:"Activeness — Situational",trait:"Can't sit through anything, can lie in all day",desc:"Restless and loud in any chair or queue; entirely capable of a full day horizontal.",example:"(paced the whole film. Didn't leave bed on Sunday.)",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-posture",reviewStatus:"reviewed"},
{id:160123,section:"Personality Traits",category:"Activeness — Situational",trait:"Manic on holiday, inert at home",desc:"Enormous energy the moment they are somewhere else; almost none in their own rooms.",example:"(climbed three mountains abroad. Hasn't taken the bins out since.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-place",reviewStatus:"reviewed",conditions:["home"]},
{id:160124,section:"Personality Traits",category:"Activeness — Situational",trait:"Energy arrives with music",desc:"Sluggish in silence; a small, reliable lift the moment there's anything to move to.",example:"(the dishes only get done if something's playing)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-music",reviewStatus:"reviewed"},
{id:160125,section:"Personality Traits",category:"Curiosity — Situational",trait:"Curious about the dead, not the living",desc:"Endless questions about history and the long gone; none at all about the people in the room.",example:"(knows every detail of the 1840s occupants. Hasn't asked your surname.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"situational-history",reviewStatus:"reviewed"},
{id:160126,section:"Personality Traits",category:"Curiosity — Situational",trait:"Questions everything about the menu",desc:"Ordinary, loud, unstoppable inquiry about food and drink — and nothing else all evening.",example:"Is it the same lamb as the shank? Where's the lamb from? Is the shank local?",intensity:4,rarity:"common",pol:{},conceptFamily:"situational-food",reviewStatus:"reviewed"},
{id:160127,section:"Personality Traits",category:"Curiosity — Situational",trait:"Investigates only what's forbidden",desc:"Incurious about anything offered; obsessively inquisitive about anything withheld.",example:"(the open archive bores them. The locked drawer is a three-week project.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"situational-forbidden",reviewStatus:"reviewed"},
{id:160128,section:"Personality Traits",category:"Curiosity — Situational",trait:"Asks one good question per month",desc:"Rarely inquisitive; every so often a single, exact question that shows they'd been paying attention all along.",example:"(silent for weeks. Then: 'Why does the ledger skip March?')",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"situational-rare-question",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Build — Imposing
{id:160129,section:"Appearance",category:"Build — Imposing",trait:"Big hands, careful with cups",desc:"Large, strong hands that handle small things with visible, practised gentleness.",example:"(the teacup vanishes in the hand and arrives unbroken)",intensity:1,rarity:"signature",pol:{},conceptFamily:"build-large-gentle",reviewStatus:"reviewed"},
{id:160130,section:"Appearance",category:"Build — Imposing",trait:"Tall, and apologises for it",desc:"Height carried with a permanent slight stoop and a reflex 'sorry' in doorways and crowds.",example:"Sorry — sorry — (ducks) — sorry.",intensity:2,rarity:"signature",pol:{},conceptFamily:"build-tall-apology",reviewStatus:"reviewed"},
{id:160131,section:"Appearance",category:"Build — Imposing",trait:"Broad in the shoulder, narrow everywhere else",desc:"A frame that reads big from the front and surprisingly slight from the side.",example:"(a wall coming toward you; a fence post going away)",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"build-shape",reviewStatus:"reviewed"},
{id:160132,section:"Appearance",category:"Build — Imposing",trait:"Heavier than they look, lighter than they move",desc:"A solid frame carried with unexpected quietness — no creak, no thump.",example:"(you don't hear them on the stairs, which given the size is unsettling)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"build-quiet-mass",reviewStatus:"reviewed"},
{id:160133,section:"Appearance",category:"Build — Imposing",trait:"Blocks the light in every doorway",desc:"An ordinary, obvious bigness — every entrance dims for a second and everyone looks up.",example:"(the room goes briefly dark; it's just them arriving)",intensity:4,rarity:"common",pol:{},conceptFamily:"build-doorway",reviewStatus:"reviewed"},
{id:160134,section:"Appearance",category:"Build — Imposing",trait:"Built for lifting, dressed for the office",desc:"A labourer's frame in professional clothes that were never cut for it.",example:"(the jacket surrenders across the back every time they reach)",intensity:3,rarity:"common",pol:{},conceptFamily:"build-clothes",reviewStatus:"reviewed"},
{id:160135,section:"Appearance",category:"Build — Imposing",trait:"Mistaken for security everywhere",desc:"So large and still that strangers reflexively ask them where the toilets are.",example:"Excuse me, are you— — No. — Sorry. — Downstairs, on the left.",intensity:5,rarity:"common",pol:{},conceptFamily:"build-mistaken",reviewStatus:"reviewed"},
{id:160136,section:"Appearance",category:"Build — Imposing",trait:"Furniture bends to accommodate",desc:"Chairs are chosen for them, sofas sag toward them; the physical world visibly adjusts.",example:"(the good chair is 'their' chair for structural reasons)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"build-furniture",reviewStatus:"reviewed"},
{id:160137,section:"Appearance",category:"Build — Imposing",trait:"Strong enough to be asked, tired of being asked",desc:"Visibly capable of moving anything, and worn down by a lifetime of being the one who does.",example:"(the piano. Again. 'Could you just—' Yes. They could just.)",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"build-asked",reviewStatus:"reviewed"},
{id:160138,section:"Appearance",category:"Build — Imposing",trait:"A neck that suggests the rest",desc:"Nothing about the clothes gives it away; the neck and wrists tell you exactly how strong they are.",example:"(the collar doesn't quite close, and never has)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"build-hint",reviewStatus:"reviewed"},
{id:160139,section:"Appearance",category:"Build — Imposing",trait:"Uses the size as a full stop",desc:"Doesn't threaten or loom — simply stands up, and the conversation ends.",example:"(rises. That's the whole rebuttal.)",intensity:4,rarity:"distinctive",pol:{asrt:1},conceptFamily:"build-stand",reviewStatus:"reviewed"},
{id:160140,section:"Appearance",category:"Build — Imposing",trait:"Big frame, small voice",desc:"An imposing body carrying a quiet, high, or hesitant voice that startles people on first contact.",example:"(the room braces; then a voice like a librarian's)",intensity:3,rarity:"signature",pol:{},conceptFamily:"build-voice",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Build — Slight
{id:160141,section:"Appearance",category:"Build — Slight",trait:"Wrists that a hand could circle",desc:"Fine-boned in a way that shows only at the wrists and ankles, and only if you look.",example:"(the watch strap on its tightest hole, and still loose)",intensity:1,rarity:"signature",pol:{},conceptFamily:"slight-wrists",reviewStatus:"reviewed"},
{id:160142,section:"Appearance",category:"Build — Slight",trait:"Small, and precise with space",desc:"A slight frame used exactly — fits into gaps, sits on ledges, is never in the way.",example:"(perched on the windowsill where nobody else would fit, reading)",intensity:2,rarity:"signature",pol:{},conceptFamily:"slight-precision",reviewStatus:"reviewed"},
{id:160143,section:"Appearance",category:"Build — Slight",trait:"Cold in every room",desc:"A thinness that means a jumper indoors, always, and a hand round every hot drink.",example:"(the cardigan is not a fashion choice; it's a climate policy)",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"slight-cold",reviewStatus:"reviewed"},
{id:160144,section:"Appearance",category:"Build — Slight",trait:"Looks younger from behind",desc:"A slight build that reads as a teenager's until they turn around.",example:"(a kid, from the back. Then the face, and the forty years in it.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"slight-age",reviewStatus:"reviewed"},
{id:160145,section:"Appearance",category:"Build — Slight",trait:"Lifted by the wind, cheerfully",desc:"So light that weather is a genuine event — hair, coat and sometimes person go where the gust does.",example:"(the umbrella took them three steps sideways and they laughed)",intensity:4,rarity:"common",pol:{},conceptFamily:"slight-wind",reviewStatus:"reviewed"},
{id:160146,section:"Appearance",category:"Build — Slight",trait:"Wears clothes as a tent",desc:"Everything is a size too large and worn like a robe — comfortable, shapeless, obvious.",example:"(the sleeves have never seen the hands)",intensity:3,rarity:"common",pol:{},conceptFamily:"slight-clothes",reviewStatus:"reviewed"},
{id:160147,section:"Appearance",category:"Build — Slight",trait:"Carried off, regularly, by enthusiasm",desc:"Small enough to be lifted, spun, or moved aside by bigger friends, which happens constantly and loudly.",example:"(picked up mid-sentence for the fourth time this evening)",intensity:5,rarity:"common",pol:{},conceptFamily:"slight-lifted",reviewStatus:"reviewed"},
{id:160148,section:"Appearance",category:"Build — Slight",trait:"Bird-boned and completely fearless",desc:"A visibly fragile frame that walks into every confrontation first.",example:"(five foot nothing, at the front of the line, arms folded)",intensity:5,rarity:"uncommon",pol:{asrt:1},conceptFamily:"slight-fearless",reviewStatus:"reviewed"},
{id:160149,section:"Appearance",category:"Build — Slight",trait:"Underestimated in every doorway",desc:"Slight enough that people talk over them, step in front of them, and then remember them for years.",example:"(the security guard looked past them. The security guard has since been corrected.)",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"slight-underestimated",reviewStatus:"reviewed"},
{id:160150,section:"Appearance",category:"Build — Slight",trait:"Sits with feet not reaching",desc:"In most chairs the feet swing or tuck up; a small, permanent domestic fact.",example:"(the barstool is a project)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"slight-feet",reviewStatus:"reviewed"},
{id:160151,section:"Appearance",category:"Build — Slight",trait:"Thin from illness, not choice",desc:"A recent, visible slightness that the clothes haven't caught up with and that people notice and don't mention.",example:"(the belt has a new hole, hand-punched)",intensity:4,rarity:"distinctive",pol:{},conceptFamily:"slight-illness",reviewStatus:"reviewed"},
{id:160152,section:"Appearance",category:"Build — Slight",trait:"Runner's frame, smoker's cough",desc:"Built like an athlete and audibly not one.",example:"(the build says marathon. The lungs say otherwise.)",intensity:3,rarity:"signature",pol:{},conceptFamily:"slight-contradiction",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Upkeep — Immaculate
{id:160153,section:"Appearance",category:"Upkeep — Immaculate",trait:"Shoes polished the night before, always",desc:"A quiet, unbroken evening ritual that nobody sees and everybody benefits from.",example:"(two pairs, by the door, gleaming, every single morning)",intensity:1,rarity:"signature",pol:{disc:1},conceptFamily:"upkeep-shoes",reviewStatus:"reviewed"},
{id:160154,section:"Appearance",category:"Upkeep — Immaculate",trait:"One perfect handkerchief",desc:"Nothing showy; a single pressed, folded cloth that is always exactly where it should be.",example:"(offered, clean, before you knew you'd need it)",intensity:2,rarity:"signature",pol:{disc:1},conceptFamily:"upkeep-handkerchief",reviewStatus:"reviewed"},
{id:160155,section:"Appearance",category:"Upkeep — Immaculate",trait:"Nails always short, always clean",desc:"A small, constant, unremarked standard kept regardless of the work.",example:"(the hands came out of the engine and were somehow already clean)",intensity:2,rarity:"distinctive",pol:{disc:1},conceptFamily:"upkeep-nails",reviewStatus:"reviewed"},
{id:160156,section:"Appearance",category:"Upkeep — Immaculate",trait:"Hair that has one shape",desc:"A style set decades ago and maintained since, unchanged by weather, fashion or age.",example:"(the same parting as the 1994 photo, to the millimetre)",intensity:1,rarity:"distinctive",pol:{disc:1},conceptFamily:"upkeep-hair",reviewStatus:"reviewed"},
{id:160157,section:"Appearance",category:"Upkeep — Immaculate",trait:"Ironed to the point of comment",desc:"Ordinary neatness done so thoroughly that people mention it, often.",example:"Did you iron the socks? — Yes. — The SOCKS? — Yes.",intensity:4,rarity:"common",pol:{disc:1},conceptFamily:"upkeep-ironing",reviewStatus:"reviewed"},
{id:160158,section:"Appearance",category:"Upkeep — Immaculate",trait:"Lint-rolls in public",desc:"Visible, frequent, unembarrassed maintenance — the brush, the roller, the wet wipe — wherever they are.",example:"(mid-conversation, a lint roller appears and does its work)",intensity:3,rarity:"common",pol:{disc:1},conceptFamily:"upkeep-public",reviewStatus:"reviewed"},
{id:160159,section:"Appearance",category:"Upkeep — Immaculate",trait:"Changes outfit for each part of the day",desc:"Morning, work, evening, dinner — each has its own clothes, and the changes are announced.",example:"Right, I'll just go and put my evening things on. — It's four.",intensity:5,rarity:"common",pol:{disc:1},conceptFamily:"upkeep-changes",reviewStatus:"reviewed"},
{id:160160,section:"Appearance",category:"Upkeep — Immaculate",trait:"Won't sit until the seat's been checked",desc:"An extreme, visible fastidiousness — surfaces inspected, wiped, sometimes declined.",example:"(the napkin goes on the chair before they do, every time)",intensity:5,rarity:"uncommon",pol:{disc:1},conceptFamily:"upkeep-seat",reviewStatus:"reviewed"},
{id:160161,section:"Appearance",category:"Upkeep — Immaculate",trait:"Straightens strangers' collars",desc:"Straightens your collar, brushes your shoulder, fixes your hair — reflexively, on anyone.",example:"(reaches across the table and rebuttons the stranger's cuff)",intensity:4,rarity:"uncommon",pol:{disc:1},conceptFamily:"upkeep-others",reviewStatus:"reviewed"},
{id:160162,section:"Appearance",category:"Upkeep — Immaculate",trait:"Scent chosen, never noticed",desc:"A faint, consistent, expensive fragrance that people register only as 'they always smell nice'.",example:"(you couldn't name it. You'd know it in the dark.)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"upkeep-scent",reviewStatus:"reviewed"},
{id:160163,section:"Appearance",category:"Upkeep — Immaculate",trait:"Immaculate under the overalls",desc:"Filthy outer work clothes over a pressed shirt and clean everything, visible only at the collar.",example:"(the boilersuit is black with oil. The cuff under it is white.)",intensity:4,rarity:"distinctive",pol:{disc:1},conceptFamily:"upkeep-layers",reviewStatus:"reviewed"},
{id:160164,section:"Appearance",category:"Upkeep — Immaculate",trait:"Neat as a kind of silence",desc:"Perfect presentation used to give nothing away — no stain, no crease, no clue.",example:"(you learn nothing from the clothes; that's what they're for)",intensity:3,rarity:"signature",pol:{emo:-1},conceptFamily:"upkeep-silence",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Upkeep — Unkempt
{id:160165,section:"Appearance",category:"Upkeep — Unkempt",trait:"One button always missed",desc:"Otherwise presentable; there is, invariably, one button undone or misaligned somewhere.",example:"(the shirt is off by one from the second button down. It's always the second.)",intensity:1,rarity:"signature",pol:{disc:-1},conceptFamily:"unkempt-button",reviewStatus:"reviewed"},
{id:160166,section:"Appearance",category:"Upkeep — Unkempt",trait:"A thread they've never cut",desc:"A single loose thread on a favourite coat, years old, unattended, part of them now.",example:"(the sleeve thread has been there since the wedding)",intensity:2,rarity:"signature",pol:{disc:-1},conceptFamily:"unkempt-thread",reviewStatus:"reviewed"},
{id:160167,section:"Appearance",category:"Upkeep — Unkempt",trait:"Odd socks, consistently",desc:"Never matching, never noticed by them, always noticed by everyone else.",example:"(one navy, one green, both confident)",intensity:2,rarity:"distinctive",pol:{disc:-1},conceptFamily:"unkempt-socks",reviewStatus:"reviewed"},
{id:160168,section:"Appearance",category:"Upkeep — Unkempt",trait:"Pen marks on the hand",desc:"A small, permanent smudge of ink at the side of the hand from writing and forgetting.",example:"(the edge of the palm is blue. It's been blue since school.)",intensity:1,rarity:"distinctive",pol:{disc:-1},conceptFamily:"unkempt-ink",reviewStatus:"reviewed"},
{id:160169,section:"Appearance",category:"Upkeep — Unkempt",trait:"Crumbs are a permanent feature",desc:"Ordinary, cheerful, constant evidence of the last meal, on the front, at all times.",example:"(you can tell what they had for lunch from across the room)",intensity:4,rarity:"common",pol:{disc:-1},conceptFamily:"unkempt-crumbs",reviewStatus:"reviewed"},
{id:160170,section:"Appearance",category:"Upkeep — Unkempt",trait:"Slept in it, obviously",desc:"Clothes that carry the clear, unmistakable shape of a night on a sofa.",example:"(the creases form a map of the cushions)",intensity:3,rarity:"common",pol:{disc:-1},conceptFamily:"unkempt-slept",reviewStatus:"reviewed"},
{id:160171,section:"Appearance",category:"Upkeep — Unkempt",trait:"Loudly beyond caring",desc:"Not merely untidy — announces the untidiness, defends it, and makes it a position.",example:"I haven't washed this since Tuesday and I'm PROUD of that.",intensity:5,rarity:"common",pol:{disc:-1,rebel:1},conceptFamily:"unkempt-defiant",reviewStatus:"reviewed"},
{id:160172,section:"Appearance",category:"Upkeep — Unkempt",trait:"Smells of the workshop, always",desc:"Solvent, sawdust, smoke or animal — the trade arrives a full second before they do.",example:"(you know they're in the building; you don't know how far away)",intensity:5,rarity:"uncommon",pol:{disc:-1},conceptFamily:"unkempt-smell",reviewStatus:"reviewed"},
{id:160173,section:"Appearance",category:"Upkeep — Unkempt",trait:"Hasn't owned a comb in a decade",desc:"Hair managed entirely by hands, hats and weather, at full visibility.",example:"(the hair has a system. The system is not grooming.)",intensity:4,rarity:"uncommon",pol:{disc:-1},conceptFamily:"unkempt-comb",reviewStatus:"reviewed"},
{id:160174,section:"Appearance",category:"Upkeep — Unkempt",trait:"Glasses permanently smudged",desc:"Sees the world through a light haze and has stopped noticing.",example:"(cleans them on the shirt, which makes it worse)",intensity:1,rarity:"uncommon",pol:{disc:-1},conceptFamily:"unkempt-glasses",reviewStatus:"reviewed"},
{id:160175,section:"Appearance",category:"Upkeep — Unkempt",trait:"Untidy by grief, recently",desc:"A new, visible slide in upkeep that people around them have noticed and are being careful about.",example:"(the beard is new. So is the reason.)",intensity:4,rarity:"distinctive",pol:{disc:-1,mood:-1},conceptFamily:"unkempt-grief",reviewStatus:"reviewed"},
{id:160176,section:"Appearance",category:"Upkeep — Unkempt",trait:"Careless of self, careful of tools",desc:"Personally rumpled; the instruments, knives, brushes or books are kept like relics.",example:"(the coat is a disgrace. The chisels could perform surgery.)",intensity:3,rarity:"signature",pol:{disc:-1},conceptFamily:"unkempt-tools",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Presence — Striking
{id:160177,section:"Appearance",category:"Presence — Striking",trait:"Remembered by the hands",desc:"Ordinary face; the hands — long, scarred, expressive — are what people describe afterwards.",example:"'The one with the hands.' Everyone nods.",intensity:1,rarity:"signature",pol:{},conceptFamily:"striking-hands",reviewStatus:"reviewed"},
{id:160178,section:"Appearance",category:"Presence — Striking",trait:"Striking only when speaking",desc:"Plain in repose; something about the face in motion that makes people stop and listen.",example:"(the photo is nothing. The conversation, you'd cross a room for.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"striking-animated",reviewStatus:"reviewed"},
{id:160179,section:"Appearance",category:"Presence — Striking",trait:"Eyes of two different colours",desc:"A small, permanent oddity that every new acquaintance notices second and mentions first.",example:"Your eyes are— — Yes. — Sorry. — It's fine. Everyone does.",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"striking-eyes",reviewStatus:"reviewed"},
{id:160180,section:"Appearance",category:"Presence — Striking",trait:"A profile made for coins",desc:"Unremarkable head-on; from the side, a nose and jaw that belong on currency.",example:"(the sculptor asked them to turn. Then asked them not to turn back.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"striking-profile",reviewStatus:"reviewed"},
{id:160181,section:"Appearance",category:"Presence — Striking",trait:"Dresses to be looked at, and is",desc:"Ordinary good looks amplified by loud, deliberate, effective clothes.",example:"(the coat is red. The coat is always red. The coat works.)",intensity:4,rarity:"common",pol:{},conceptFamily:"striking-dress",reviewStatus:"reviewed"},
{id:160182,section:"Appearance",category:"Presence — Striking",trait:"Tall enough to be the landmark",desc:"Height that makes them the agreed meeting point in any crowd.",example:"Where are you? — Look up.",intensity:3,rarity:"common",pol:{},conceptFamily:"striking-height",reviewStatus:"reviewed"},
{id:160183,section:"Appearance",category:"Presence — Striking",trait:"Recognised by strangers, constantly",desc:"A face so memorable that people are sure they know it — from television, school, somewhere — daily.",example:"Sorry, do I know you? — No. — Are you sure? — Fairly.",intensity:5,rarity:"common",pol:{},conceptFamily:"striking-recognised",reviewStatus:"reviewed"},
{id:160184,section:"Appearance",category:"Presence — Striking",trait:"Beautiful in a way that scares people",desc:"Looks that make new acquaintances stammer, avoid eye contact, or overcorrect into rudeness.",example:"(three people have been strange to them today and none know why)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"striking-intimidating",reviewStatus:"reviewed"},
{id:160185,section:"Appearance",category:"Presence — Striking",trait:"A face that has been famous once",desc:"Was, briefly, somebody — and still carries that lit-up quality people can't place.",example:"(the barista keeps looking. The barista was born after the poster.)",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"striking-former",reviewStatus:"reviewed"},
{id:160186,section:"Appearance",category:"Presence — Striking",trait:"One white streak in the hair",desc:"A single, natural, unmissable band of grey or white that arrived early and stayed.",example:"(had it at nineteen. Has been asked about it at every party since.)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"striking-streak",reviewStatus:"reviewed"},
{id:160187,section:"Appearance",category:"Presence — Striking",trait:"Lit from within when angry",desc:"Plain until furious; then a colour and a stillness that make the room go quiet.",example:"(everyone stops talking a half-second before they do)",intensity:4,rarity:"distinctive",pol:{},conceptFamily:"striking-anger",reviewStatus:"reviewed"},
{id:160188,section:"Appearance",category:"Presence — Striking",trait:"Striking, and tired of it",desc:"Looks that draw attention they no longer want, managed with plain clothes that don't help.",example:"(the hat, the glasses, the corner table. Doesn't work. Never has.)",intensity:3,rarity:"signature",pol:{},conceptFamily:"striking-tired",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Presence — Unremarkable
{id:160189,section:"Appearance",category:"Presence — Unremarkable",trait:"One thing they change to be seen",desc:"Invisible by default; a single deliberate signal — a hat, a brooch, a colour — on the days they want noticing.",example:"(the yellow scarf means 'today, I'd like to be spoken to')",intensity:1,rarity:"signature",pol:{},conceptFamily:"plain-signal",reviewStatus:"reviewed"},
{id:160190,section:"Appearance",category:"Presence — Unremarkable",trait:"The face in every group photo, unnamed",desc:"Present in decades of pictures and identified in none of the captions.",example:"(third from left. 'And a friend.' Every single time.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"plain-photo",reviewStatus:"reviewed"},
{id:160191,section:"Appearance",category:"Presence — Unremarkable",trait:"Looks like the job title",desc:"So exactly what a clerk, a nurse or a driver is expected to look like that the person disappears into the role.",example:"'The nurse.' Not a name. Never a name.",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"plain-role",reviewStatus:"reviewed"},
{id:160192,section:"Appearance",category:"Presence — Unremarkable",trait:"Mistaken for someone else, gently",desc:"Regularly greeted with the wrong name and too polite to correct it.",example:"Morning, Paul! — (is not Paul; has answered to Paul for six years)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"plain-mistaken",reviewStatus:"reviewed"},
{id:160193,section:"Appearance",category:"Presence — Unremarkable",trait:"Loudly, cheerfully average",desc:"Entirely ordinary in every feature and says so, often, as a point of pride.",example:"Face like a potato. Proud of it. Good, honest potato.",intensity:4,rarity:"common",pol:{},conceptFamily:"plain-proud",reviewStatus:"reviewed"},
{id:160194,section:"Appearance",category:"Presence — Unremarkable",trait:"Dressed from the same rail for years",desc:"Ordinary, unchanging, practical clothes in the same three colours since forever.",example:"(navy, grey, navy. There was a beige once. It didn't take.)",intensity:3,rarity:"common",pol:{},conceptFamily:"plain-wardrobe",reviewStatus:"reviewed"},
{id:160195,section:"Appearance",category:"Presence — Unremarkable",trait:"Overlooked by shop assistants, every time",desc:"So unremarkable that service passes over them in favour of whoever came in after — visibly, daily.",example:"I was here first. — Sorry, I didn't see you. — Nobody does.",intensity:5,rarity:"common",pol:{},conceptFamily:"plain-overlooked",reviewStatus:"reviewed"},
{id:160196,section:"Appearance",category:"Presence — Unremarkable",trait:"Invisible enough to have used it",desc:"Has, more than once, walked into places they shouldn't be, purely on being unnoticeable.",example:"(nobody asked for a pass. Nobody has ever asked for a pass.)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"plain-access",reviewStatus:"reviewed"},
{id:160197,section:"Appearance",category:"Presence — Unremarkable",trait:"Forgotten by the people they've helped",desc:"Did the kind thing, was thanked, and is not recognised the next week.",example:"(pulled the child from the pond. The parents walked past on Sunday.)",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"plain-forgotten",reviewStatus:"reviewed"},
{id:160198,section:"Appearance",category:"Presence — Unremarkable",trait:"A voice more memorable than the face",desc:"Plain to look at; instantly placed the moment they speak.",example:"Who's that? — (they say hello) — Oh! It's you!",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"plain-voice",reviewStatus:"reviewed"},
{id:160199,section:"Appearance",category:"Presence — Unremarkable",trait:"Wears the uniform of whoever's around",desc:"Adopts the dress of any group within a week and vanishes into it.",example:"(a month in and indistinguishable from the regulars, again)",intensity:4,rarity:"distinctive",pol:{},conceptFamily:"plain-chameleon",reviewStatus:"reviewed"},
{id:160200,section:"Appearance",category:"Presence — Unremarkable",trait:"Plain on purpose, and it's a skill",desc:"Could stand out and has chosen not to — the plainness is maintained, deliberately, like a garden.",example:"(the good coat stays in the wardrobe. That's a decision, renewed daily.)",intensity:3,rarity:"signature",pol:{},conceptFamily:"plain-chosen",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Movement & Bearing
{id:160201,section:"Appearance",category:"Movement & Bearing",trait:"Pauses at every threshold",desc:"A tiny, invariable halt before entering any room — a breath, a look, then in.",example:"(one beat at the door. Always one beat. Then through.)",intensity:1,rarity:"signature",pol:{},conceptFamily:"bearing-threshold",reviewStatus:"reviewed"},
{id:160202,section:"Appearance",category:"Movement & Bearing",trait:"Walks the long way, quietly",desc:"Takes the slightly longer route, every time, without hurry or explanation.",example:"(round the square rather than across it. Always. Nobody asks why.)",intensity:2,rarity:"signature",pol:{act:-1},conceptFamily:"bearing-route",reviewStatus:"reviewed"},
{id:160203,section:"Appearance",category:"Movement & Bearing",trait:"Hands clasped behind, always",desc:"A small fixed posture — hands behind the back — in every situation from queues to funerals.",example:"(inspecting the vegetables like a general)",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"bearing-hands",reviewStatus:"reviewed"},
{id:160204,section:"Appearance",category:"Movement & Bearing",trait:"Stands slightly too close",desc:"A personal-space radius a few inches short of everyone else's, unnoticed by them, noticed by all.",example:"(everyone in the conversation has taken one step back. They have taken one forward.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"bearing-proximity",reviewStatus:"reviewed"},
{id:160205,section:"Appearance",category:"Movement & Bearing",trait:"Bounds up stairs two at a time",desc:"Ordinary, loud, physical eagerness — takes every staircase at a run, at every age.",example:"(you hear them arrive a floor before they do)",intensity:4,rarity:"common",pol:{act:1},conceptFamily:"bearing-stairs",reviewStatus:"reviewed"},
{id:160206,section:"Appearance",category:"Movement & Bearing",trait:"Sighs when sitting down",desc:"The universal small noise on reaching a chair, produced reliably and with feeling.",example:"(hhhaaaah. Right.)",intensity:3,rarity:"common",pol:{},conceptFamily:"bearing-sigh",reviewStatus:"reviewed"},
{id:160207,section:"Appearance",category:"Movement & Bearing",trait:"Never still, not for a second",desc:"Constant, loud, visible motion — foot, hand, chair, pen — in every room, at every meeting.",example:"(the table is vibrating. It's their knee. It's always their knee.)",intensity:5,rarity:"common",pol:{act:1},conceptFamily:"bearing-fidget",reviewStatus:"reviewed"},
{id:160208,section:"Appearance",category:"Movement & Bearing",trait:"Moves like they're on a stage",desc:"Every gesture pitched to the back row, at full size, whether or not anyone is watching.",example:"(reaches for the salt as if presenting it to an audience)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"bearing-theatrical",reviewStatus:"reviewed"},
{id:160209,section:"Appearance",category:"Movement & Bearing",trait:"Limps on the left, denies it",desc:"A visible, permanent hitch in the walk and a firm, repeated insistence that there isn't one.",example:"You're limping. — I'm not. — You are. — It's the shoe.",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"bearing-limp",reviewStatus:"reviewed"},
{id:160210,section:"Appearance",category:"Movement & Bearing",trait:"Rotates rather than glances",desc:"Doesn't glance — rotates, shoulders and all, to face anything worth seeing.",example:"(the head doesn't turn. The person does.)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"bearing-turn",reviewStatus:"reviewed"},
{id:160211,section:"Appearance",category:"Movement & Bearing",trait:"Walks as if carrying something breakable",desc:"A careful, level, slightly slow gait, even empty-handed — every step placed.",example:"(crossing a bare room like it's a minefield of eggs)",intensity:4,rarity:"distinctive",pol:{act:-1},conceptFamily:"bearing-careful",reviewStatus:"reviewed"},
{id:160212,section:"Appearance",category:"Movement & Bearing",trait:"Stillness that reads as threat",desc:"Doesn't fidget, doesn't shift — a stillness so complete that people find it alarming.",example:"(has not moved in twenty minutes. The room has arranged itself accordingly.)",intensity:3,rarity:"signature",pol:{act:-1},conceptFamily:"bearing-still",reviewStatus:"reviewed"},

// ---------------------------------------------------------------- Appearance: Distinguishing Marks
{id:160213,section:"Appearance",category:"Distinguishing Marks",trait:"A ring on the wrong finger",desc:"One ring, worn where rings aren't usually worn, never explained.",example:"(the thumb. Silver. Nobody knows whose it was.)",intensity:1,rarity:"signature",pol:{},conceptFamily:"marks-ring",reviewStatus:"reviewed"},
{id:160214,section:"Appearance",category:"Distinguishing Marks",trait:"A burn healed in the shape of something",desc:"An old scar that, if you look, forms a rough letter or figure — and they know which.",example:"(the mark on the forearm is nearly an M. It's for someone.)",intensity:2,rarity:"signature",pol:{},conceptFamily:"marks-burn",reviewStatus:"reviewed"},
{id:160215,section:"Appearance",category:"Distinguishing Marks",trait:"Freckles that map the summers",desc:"A face that shows exactly how much sun the year had, every year.",example:"(the August version and the February version are different people)",intensity:2,rarity:"distinctive",pol:{},conceptFamily:"marks-freckles",reviewStatus:"reviewed"},
{id:160216,section:"Appearance",category:"Distinguishing Marks",trait:"A chipped front tooth, unrepaired",desc:"A small, old, visible chip that they could have fixed and haven't, for reasons.",example:"(smiles anyway. The chip has a story; the story has a person in it.)",intensity:1,rarity:"distinctive",pol:{},conceptFamily:"marks-tooth",reviewStatus:"reviewed"},
{id:160217,section:"Appearance",category:"Distinguishing Marks",trait:"Tattoos they explain unprompted",desc:"Ordinary ink, on show, with a story for each one delivered whether you asked or not.",example:"This one's Bali. This one's my nan. This one's a mistake, I'll tell you about it.",intensity:4,rarity:"common",pol:{},conceptFamily:"marks-tattoo-story",reviewStatus:"reviewed"},
{id:160218,section:"Appearance",category:"Distinguishing Marks",trait:"Glasses pushed up into the hair",desc:"Reading glasses that live on top of the head and are searched for there, daily, in full view.",example:"Has anyone seen my— — They're on your head. — They're not— oh.",intensity:3,rarity:"common",pol:{},conceptFamily:"marks-glasses",reviewStatus:"reviewed"},
{id:160219,section:"Appearance",category:"Distinguishing Marks",trait:"A laugh you can hear across a car park",desc:"A common enough feature — a big laugh — at a volume that identifies them from a hundred yards.",example:"(the whole street knows they've arrived at the pub)",intensity:5,rarity:"common",pol:{vol:1},conceptFamily:"marks-laugh",reviewStatus:"reviewed"},
{id:160220,section:"Appearance",category:"Distinguishing Marks",trait:"Missing a finger, uses the gap",desc:"A visible absence turned into a gesture, a joke and a signature.",example:"(counts to nine on their fingers, pointedly, every time)",intensity:5,rarity:"uncommon",pol:{},conceptFamily:"marks-finger",reviewStatus:"reviewed"},
{id:160221,section:"Appearance",category:"Distinguishing Marks",trait:"A scar that changes the smile",desc:"An old injury that pulls one side of the mouth, so every expression comes with a second meaning.",example:"(the grin looks like a sneer on the left. Strangers get the wrong idea.)",intensity:4,rarity:"uncommon",pol:{},conceptFamily:"marks-smile-scar",reviewStatus:"reviewed"},
{id:160222,section:"Appearance",category:"Distinguishing Marks",trait:"A single grey eyebrow hair, tended",desc:"One long white hair in the brow, left in place with what looks like affection.",example:"(it's been there since forty. It has a name.)",intensity:1,rarity:"uncommon",pol:{},conceptFamily:"marks-brow",reviewStatus:"reviewed"},
{id:160223,section:"Appearance",category:"Distinguishing Marks",trait:"Hands stained by the trade, permanently",desc:"Dye, nicotine, earth or ink worked into the skin past any washing — the work written on them.",example:"(the fingers are indigo to the second knuckle and have been for thirty years)",intensity:4,rarity:"distinctive",pol:{},conceptFamily:"marks-stained",reviewStatus:"reviewed"},
{id:160224,section:"Appearance",category:"Distinguishing Marks",trait:"A mark they cover in company",desc:"Something on the skin — a birthmark, a scar, a tattoo — kept under a sleeve or collar in public and forgotten at home.",example:"(the cuff comes down at the door and goes up again at the sink)",intensity:3,rarity:"signature",pol:{},conceptFamily:"marks-hidden",reviewStatus:"reviewed",conditions:["public"]},
];

